const state={queue:[],id:null,detail:null,tab:'overview',page:'home',filter:'all',historyOpen:false,historyFilter:'all',historySource:null,historySourceId:null,reference:null,referenceCandidate:null,referenceLibrary:null,referenceDetail:null,matchResult:null,staticDemo:Boolean(location.hostname)&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname),research:null};
const el=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label={escalate:'Needs closer review',review_required:'Needs judgement',routine_candidate:'Looks routine',blocked_extraction:'Analysis blocked'};
const decisionLabel={approve:'Approved by reviewer',request_amendment:'Amendment requested',reject:'Rejected by reviewer',escalate:'Escalated by reviewer'};
const filterLabel={all:'All contracts',escalate:'Needs closer review',review_required:'Needs judgement',routine_candidate:'Looks routine',blocked_extraction:'Analysis blocked'};
const validFilters=new Set(Object.keys(filterLabel));
const savedFilter=sessionStorage.getItem('chug.queueFilter');
if(validFilters.has(savedFilter))state.filter=savedFilter;
function queueItems(filter=state.filter){return state.queue.filter(item=>filter==='all'||(item.route===filter&&!item.latest_decision))}
function toast(message){el('toast').textContent=message;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el('toast').textContent='',5000)}
async function readJson(url,options){
  const response=await fetch(url,options);
  const type=(response.headers?.get('content-type')||'application/json').toLowerCase();
  if(!type.includes('json')){const error=new Error('Expected JSON but received '+type+' from '+url);error.nonJson=true;throw error}
  let data;
  try{data=await response.json()}
  catch(cause){
    const error=new Error('Invalid or empty JSON response from '+url);
    // Static hosting may return an empty 200 response for a missing Python API.
    // Only fall back to bundled data for an otherwise successful API response.
    error.nonJson=response.ok;
    throw error;
  }
  if(!response.ok)throw new Error(data?.error||'Request failed ('+response.status+')');
  return data;
}
function staticJsonUrl(url){
  if(url==='/api/queue')return '/demo-data/queue.json';
  if(url==='/api/reference')return '/demo-data/reference.json';
  let match=url.match(/^\/api\/contracts\/([A-Za-z0-9_-]+)$/);
  if(match)return '/demo-data/contracts/'+match[1]+'.json';
  match=url.match(/^\/api\/history\/([A-Za-z0-9_-]+)$/);
  if(match)return '/demo-data/history/'+match[1]+'.json';
  if(url.startsWith('/demo-data/'))return url;
  throw new Error('This is a read-only demonstration; the Python review service is not connected.');
}
function originalUrl(url){
  if(!state.staticDemo)return url;
  let match=url.match(/^\/api\/contracts\/([A-Za-z0-9_-]+)\/original$/);
  if(match)return '/demo-data/originals/contracts/'+match[1]+'.docx';
  match=url.match(/^\/api\/history\/([A-Za-z0-9_-]+)\/original$/);
  if(match)return '/demo-data/originals/history/'+match[1]+'.docx';
  match=url.match(/^\/api\/references\/([0-9a-f]{64})\/original$/);
  if(match)return '/demo-data/originals/references/'+match[1]+'.docx';
  return url;
}
async function api(url,options){
  if(state.staticDemo){
    if((options?.method||'GET').toUpperCase()!=='GET')throw new Error('Read-only public demo: reviews, uploads and publications require the private Python service.');
    return readJson(staticJsonUrl(url));
  }
  try{return await readJson(url,options)}
  catch(error){
    if(url==='/api/queue'&&!options&&error.nonJson){
      try{
        const snapshot=await readJson('/demo-data/queue.json');
        state.staticDemo=true;
        return snapshot;
      }catch(snapshotError){throw new Error('The host has no JSON API and no exported demo data. Build web/demo-data with python3 scripts/export_public_demo.py before publishing.')}
    }
    throw error;
  }
}
function applyStaticDemo(){
  if(!state.staticDemo)return;
  const shell=el('shell');
  if(shell&&!el('demo-banner'))shell.insertAdjacentHTML('afterbegin','<div id="demo-banner" role="status"><strong>Read-only public demonstration</strong> · Synthetic documents and precomputed comparisons. No uploads, decisions, publication or AI calls are available on this website.</div>');
  document.querySelectorAll('.upload-button, [data-add-upload], .decision-action, [data-open-decision], [data-select-reference], [data-use-reference], form, #ai-run').forEach(node=>node.hidden=true);
  document.querySelectorAll('a[href^="/api/"]').forEach(link=>{link.href=originalUrl(link.getAttribute('href'))});
}

async function loadQueue(){const data=await api('/api/queue');state.queue=data.items;renderQueue();if(state.page==='home'||state.page==='queue')renderPage()}
function renderQueue(){const shown=queueItems();el('filter').value=state.filter;el('queue-count').textContent=state.filter==='all'?`${state.queue.length} ${state.queue.length===1?'contract':'contracts'} · priority first`:`${shown.length} awaiting a decision`;el('queue').innerHTML=shown.map(item=>`<button class="queue-item ${item.id===state.id?'selected':''}" data-id="${esc(item.id)}" type="button"><span class="queue-item-top"><span class="queue-item-title">${esc(item.display_name)}</span><span class="route-label ${item.route}">${label[item.route]}</span></span><span class="queue-item-sub">${item.findings_count} ${item.findings_count===1?'finding':'findings'}${item.latest_decision?' · Decision recorded':''}</span><span class="queue-reason">${esc(item.reason)}</span></button>`).join('')||'<p class="empty">No contracts awaiting a decision in this view. Choose All contracts to see completed reviews.</p>';el('queue').querySelectorAll('[data-id]').forEach(button=>button.onclick=()=>select(button.dataset.id));applyStaticDemo()}
function route(){const parts=location.hash.slice(1).split('/');return {page:['home','queue','reference','help','explore','review'].includes(parts[0])?parts[0]:'home',id:parts[1]?decodeURIComponent(parts[1]):null,tab:parts[2]||'overview',anchor:parts[3]?decodeURIComponent(parts[3]):null}}
async function navigate(page,id=null,tab='overview',anchor=null,replace=false){if(page==='queue'){state.filter=validFilters.has(id)?id:'all';sessionStorage.setItem('chug.queueFilter',state.filter)}const hash=page==='review'&&id?'#review/'+[id,tab,...(anchor?[anchor]:[])].map(encodeURIComponent).join('/'):page==='queue'&&state.filter!=='all'?'#queue/'+state.filter:'#'+page;if(location.hash!==hash)window.history[replace?'replaceState':'pushState'](null,'',hash);if(page==='review'&&id!==state.id){state.findingOpen=null;state.historyFilter='all'}state.page=page;state.historyOpen=false;state.historySource=null;if(page==='home'||page==='queue'){try{const data=await api('/api/queue');state.queue=data.items;renderQueue()}catch(err){el('workspace').innerHTML=`<p class="empty">${esc(err.message)}</p>`;return}}if(page==='review'&&id){state.id=id;state.tab=tab;renderQueue();el('workspace').innerHTML='<div class="loading">Opening document…</div>';try{state.detail=await api(`/api/contracts/${encodeURIComponent(id)}`)}catch(err){el('workspace').innerHTML=`<p class="empty">${esc(err.message)}</p>`;return}}renderPage(anchor)}
async function select(id){await navigate('review',id)}
function setTab(tab,anchor){return navigate('review',state.id,tab,anchor)}
function sourceBox(unit,title,kind='source'){return `<div class="evidence-box"><h4>${esc(title)}</h4>${unit?`<blockquote>${esc(unit.text)}</blockquote><a href="#${esc(unit.anchor)}" class="anchor-link" data-anchor="${esc(unit.anchor)}" data-kind="${kind}">View in full text →</a>`:kind==='reference'?'<p>Independent whole-document indicator; compare the linked provisions below.</p>':'<p>Provision absent from incoming document.</p>'}</div>`}
function findingView(f,index,brief=false){const d=state.detail;let related=f.related?.length?`<details class="related"><summary>Other provisions to consider (${f.related.length})</summary><div class="evidence-box">${f.related.map(u=>`<blockquote>${esc(u.text)}</blockquote><a href="#${esc(u.anchor)}" class="anchor-link" data-anchor="${esc(u.anchor)}" data-kind="source">View in full text →</a>`).join('')}</div></details>`:'';const lessons=(d.analysis.comparison_lessons||[]).filter(row=>row.finding_id===f.id);const sourceOptions=d.document.units.map(u=>`<option value="${esc(u.anchor)}" ${u.anchor===f.sources[0]?.anchor?'selected':''}>${esc(u.text.slice(0,85))}</option>`).join('');const referenceOptions=d.reference.units.map(u=>`<option value="${esc(u.anchor)}" ${u.anchor===f.reference?.anchor?'selected':''}>${esc(u.text.slice(0,85))}</option>`).join('');return `<details class="finding" id="finding-${index}"><summary><span class="finding-kind">${f.route==='escalate'?'Closer review':'Difference'}</span><span class="finding-title">${esc(brief?'More evidence and correction tools':f.title)}</span></summary><div class="finding-body"><p>${esc(f.explanation)}</p><div class="evidence-grid">${sourceBox(f.sources[0],'Incoming document')}${sourceBox(f.reference,'Reference wording','reference')}</div>${f.sources.length>1?`<details><summary>See ${f.sources.length-1} more source passages</summary>${f.sources.slice(1).map(u=>sourceBox(u,'Additional source')).join('')}</details>`:''}${related}${lessons.map(lesson=>`<div class="lesson"><strong>Past reviewer correction on related wording</strong><p>${esc(lesson.relationship.replaceAll('_',' '))}: ${esc(lesson.explanation)}</p><blockquote>${esc(lesson.previous_source_text)}</blockquote><p>Context: ${esc(lesson.context)} · Limits: ${esc(lesson.reuse_limits)}</p><p class="uncertainty">${esc(lesson.match_basis)}. Applicability ${esc(lesson.applicability)}. Current route and comparison are unchanged.</p><button class="text-action" data-precedent-source="${esc(lesson.previous_document_id)}" data-anchor="${esc(lesson.previous_source_anchor)}" type="button">Inspect original correction source →</button></div>`).join('')}${f.uncertainty?`<p class="uncertainty">Uncertainty: ${esc(f.uncertainty)}</p>`:''}<details class="correction-details"><summary>Improve this comparison</summary><p>Your correction records how to read this comparison. It does not decide this contract or enter future search unless separately shared.</p><form class="correction-form" data-finding="${esc(f.id)}"><label class="field">Incoming passage<select name="source_anchor"><option value="">No incoming passage</option>${sourceOptions}</select></label><label class="field">Reference passage<select name="reference_anchor"><option value="">No reference passage</option>${referenceOptions}</select></label><label class="field">Your assessment<select name="relationship" required><option value="">Choose one</option><option value="wrong_pair">Wrong clause pairing</option><option value="equivalent_candidate">Possibly equivalent</option><option value="partial_overlap">Partial overlap</option><option value="material_difference">Material difference</option><option value="overlooked_exception">Overlooked exception</option><option value="unsure">Unsure</option></select></label><label class="field">What should a later reviewer check?<textarea name="explanation" required maxlength="2000"></textarea></label><label class="field">Reviewer name<input name="reviewer" required maxlength="100"></label><button class="secondary" type="submit">Save correction</button></form></details><details class="technical"><summary>Check detail</summary><p>${esc(f.method)} check · ${esc(f.id)}</p></details></div></details>`}
function reportMissView(d){if(d.analysis.route==='blocked_extraction')return '';const sourceOptions=d.document.units.map(u=>`<option value="${esc(u.anchor)}">${esc(u.text.slice(0,90))}</option>`).join('');const referenceOptions=d.reference.units.map(u=>`<option value="${esc(u.anchor)}">${esc(u.text.slice(0,90))}</option>`).join('');return `<details class="missed-report"><summary>Something Chug missed?</summary><p>Point to an incoming or reference passage and explain the concern. This records your challenge and prevents a routine route here; it does not approve or publish anything.</p><form class="correction-form" data-finding=""><label class="field">Incoming passage<select name="source_anchor"><option value="">None / missing from incoming</option>${sourceOptions}</select></label><label class="field">Reference passage<select name="reference_anchor"><option value="">None / not in reference</option>${referenceOptions}</select></label><input type="hidden" name="relationship" value="overlooked_exception"><label class="field">What was missed?<textarea name="explanation" required maxlength="2000"></textarea></label><label class="field">Reviewer name<input name="reviewer" required maxlength="100"></label><button class="secondary" type="submit">Record missed provision</button></form></details>`}
function precedentView(p){const published=p.kind==='published_demo';return `<article class="precedent"><div class="precedent-title"><span>${published?'Published demo precedent':'Historical case'} · ${esc(p.document_id)} · ${esc(p.decision.replaceAll('_',' '))}</span><span>${esc(p.date.slice(0,10))}</span></div><span class="match-basis">${esc(p.match_basis||'same clause topic')}</span><blockquote>${esc(p.source.text)}</blockquote><button class="text-action" type="button" data-precedent-source="${esc(p.document_id)}" data-anchor="${esc(p.source.anchor)}">Inspect original passage →</button><p><strong>Why shown:</strong> ${esc(p.why_retrieved)}</p><p><strong>Past rationale:</strong> ${esc(p.rationale)}</p>${published?`<p><strong>Decision conditions:</strong> ${esc(p.conditions||'None recorded')}</p><p><strong>Commercial context:</strong> ${esc(p.context)}</p><p><strong>Reuse limits:</strong> ${esc(p.reuse_authority)}</p><p class="uncertainty">Published by ${esc(p.authoriser)} for this local demonstration. Identity is self-attested; this is not policy or approval of this contract.</p>`:`<p><strong>Reuse:</strong> ${esc(p.reuse_authority)}</p><p class="uncertainty">The historical decision is for the whole contract. Its reuse authority is illustrative only.</p>`}</article>`}
function referencePassage(d,f){
  if(f.reference)return f.reference;
  for(const related of f.related||[]){const match=d.reference.units.find(unit=>unit.text===related.text);if(match)return match}
  return null
}
function overview(d){
  const a=d.analysis,first=a.findings[0],reference=first&&referencePassage(d,first);
  const summary=first?first.explanation:a.route==='blocked_extraction'?'The document could not be fully read. Comparison and independent checks did not finish.':a.reason==='Reviewer reported a possibly missed exception'?'A reviewer has challenged the comparison. Inspect the report in Review history before deciding.':a.route==='review_required'?'No wording difference was found within the supported checks, but this selected reference is not approved guidance. Review the reference before deciding.':'No material wording change was found by the completed checks. Confirm the parties and intended transaction.';
  const other=a.findings.slice(1),past=a.precedents[0];
  const additionNote=first&&!first.reference?(reference?'This wording is added to the incoming contract. The reference does not contain the addition; its applicable protection is shown alongside it.':'This wording is added to the incoming contract. No directly paired reference passage is available; inspect the linked provisions in the finding detail.'):'';
  return `<section class="review-focus ${a.route}" aria-labelledby="review-focus-title"><div class="focus-status"><span class="route-label ${a.route}">${label[a.route]}</span><span>${d.history.length?'Human decision recorded':'Human decision needed'}</span></div><h3 class="question-title">1. What changed?</h3><p id="review-focus-title" class="finding-headline">${esc(first?first.title:a.reason)}</p><h3 class="question-title">2. Why might it matter?</h3><p class="focus-why">${esc(summary)}</p>${first?.uncertainty?`<p class="focus-uncertainty"><strong>Uncertainty:</strong> ${esc(first.uncertainty)}</p>`:''}</section>${first?`<details class="primary-evidence"><summary><span class="question-title">3. What does the original wording and reference say?</span><span class="evidence-summary-note">Open source-linked wording and applicable protection</span></summary>${additionNote?`<p class="evidence-context">${esc(additionNote)}</p>`:''}<div class="evidence-grid">${sourceBox(first.sources[0],first.reference?'Incoming wording':'Added incoming wording')}${sourceBox(reference,first.reference?'Applicable reference wording':'Reference protection','reference')}</div>${first.sources.length>1?`<details class="evidence-more"><summary>Additional evidence (${first.sources.length-1} more incoming ${first.sources.length===2?'passage':'passages'})</summary>${first.sources.slice(1).map(u=>sourceBox(u,'Additional incoming wording')).join('')}</details>`:''}</details>`:''}<section class="next-step" aria-labelledby="next-step-title"><div><h3 id="next-step-title" class="question-title">4. What should you do next?</h3><p>${d.history.length?'Review the recorded outcome or add a new human decision.':'Record your decision with a reason. The available actions are unchanged.'}</p></div><button class="primary decision-action" type="button" data-open-decision aria-controls="decision-section">${d.history.length?'Record another decision':'Record decision'}</button></section><details class="decision-disclosure" id="decision-section"><summary>Decision form</summary>${decisionView(d)}</details>${other.length?`<details class="other-findings"><summary>Other findings (${other.length})</summary><div class="finding-list">${other.map((f,i)=>findingView(f,i+1)).join('')}</div></details>`:''}${first?`<details class="finding-tools"><summary>Finding provenance, related provisions and technical check</summary>${findingView(first,0,true)}</details>`:''}${past?`<details class="past-peek"><summary>Relevant past decision (${esc(past.decision.replaceAll('_',' '))})</summary><p>A related contract was reviewed in a different context; this is not permission to reuse that outcome.</p><button class="text-action" type="button" data-history-open>Inspect past decision</button></details>`:''}${reportMissView(d)}${reviewNav(d)}<details class="review-details"><summary>Optional AI comparison</summary>${aiView(d)}</details>`
}
function assuranceView(d){const a=d.analysis.assurance;const blocked=a.extraction.status==='blocked';return `<section class="support-panel assurance"><h3>Review assurance</h3><p>${blocked?'Document content could not be fully accounted for. The remaining checks were not run.':'Checks were completed within the supported DOCX scope. This is evidence of work performed, not legal clearance.'}</p><ul class="check-list"><li>Original source <strong>${esc(a.source_integrity.status)} · SHA-256 ${esc(a.source_integrity.sha256.slice(0,12))}…</strong></li><li>Extraction <strong>${esc(a.extraction.status)} · ${esc(a.extraction.passages)} passages</strong></li><li>Reference comparison <strong>${esc(a.comparison.status)}${a.comparison.differences===null?'':` · ${a.comparison.differences} ${a.comparison.differences===1?"difference":"differences"}`}</strong></li><li>Independent indicators <strong>${esc(a.safeguards.status)}${a.safeguards.status==='complete'?` · ${a.safeguards.passages_examined} passages checked`:''}</strong></li><li>Potential escalation indicators <strong>${blocked?'not assessed':esc(a.escalation_indicators)}</strong></li><li>Human review <strong>${esc(a.human_review.status)}${a.human_review.last_decision?` · ${esc(a.human_review.last_decision.replaceAll('_',' '))}`:''}</strong></li></ul><details><summary>Scope, evidence and limits</summary><p>Source: ${esc(a.source_integrity.bytes)} bytes · full SHA-256 <code>${esc(a.source_integrity.sha256)}</code></p><p>Parts accounted for: ${esc(a.extraction.parts.join(', ')||'none')}</p><p>Comparison: ${esc(a.comparison.scope||'not run')}</p><p>Independent checks: ${esc(a.safeguards.scope||'not run')}</p>${a.limitations.length?`<ul>${a.limitations.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}<p>Open the full text for anchored passages, and download the original DOCX for its complete formatting and bytes.</p></details></section>`}
function aiView(d){let config=d.ai;const candidates=d.analysis.findings.filter(f=>f.sources.length&&f.reference);return `<section class="ai-box"><h3>Optional language comparison</h3><p>${esc(config.status)} · ${esc(config.provider)} ${esc(config.model)}. ${esc(config.transmission)} The route and human authority do not change based on this interpretation.</p>${config.available&&candidates.length?`<button class="secondary" id="ai-run" type="button" data-finding="${esc(candidates[0].id)}">Compare selected change with AI</button>`:''}${d.ai_results.map(r=>`<div class="ai-result"><strong>Live AI interpretation · ${esc(r.provider)} · ${esc(r.model)}</strong><p>${esc(r.summary)}</p><p>Possible effect: ${esc(r.possible_effect)}</p><p>Uncertainty: ${esc(r.uncertainty)}</p><small>${esc(r.timestamp)} · cited ${esc(r.source_anchors.join(', '))}</small></div>`).join('')}</section>`}
function decisionView(d){const marks=d.analysis.findings.length?`<fieldset class="considered"><legend>Findings you considered</legend><p>Select only those you inspected. Unselected findings remain visible in the review.</p>${d.analysis.findings.map(f=>`<label><input type="checkbox" name="finding" value="${esc(f.id)}"> ${esc(f.title)}</label>`).join('')}</fieldset>`:'';return `<section class="decision-panel"><h3>Record your decision</h3><p>Only a person can approve, request an amendment, reject or escalate. Your reason and the evidence you considered are saved in review history.</p><form id="decision-form">${marks}<div class="form-row"><label class="field">Reviewer name<input name="reviewer" required maxlength="100" autocomplete="name"></label><label class="field">Decision<select name="decision" required><option value="">Choose a decision</option><option value="approve">Approve</option><option value="request_amendment">Request amendment</option><option value="reject">Reject</option><option value="escalate">Escalate</option></select></label></div><label class="field">Reason for decision<textarea name="rationale" required maxlength="2000" placeholder="What did you decide, and why?"></textarea></label><label class="field">Conditions, if any<textarea name="conditions" maxlength="1000" placeholder="Limits or actions agreed as part of this decision"></textarea></label><div class="form-footer"><span class="form-note">Recording a decision does not publish it as precedent.</span><button class="primary" type="submit">Record decision</button></div></form></section>`}
function fullText(d){let previous='';return `<p class="doc-meta">Exact extracted text with source anchors. For formatting, signatures and every original byte, open the DOCX. SHA-256: <code>${esc(d.document.sha256)}</code></p>${d.document.units.map(u=>{let heading=u.part!==previous?`<h3 class="document-part">${u.part==='word/document.xml'?'Document body':esc(u.part)}</h3>`:'';previous=u.part;return `${heading}<div class="document-unit" id="${esc(u.anchor)}"><span class="document-anchor">${esc(u.anchor)}</span><span class="document-text">${esc(u.text)}</span></div>`}).join('')}`}
function historyView(d){const titles=new Map(d.analysis.findings.map(f=>[f.id,f.title]));return `<h3 class="section-title">Human decision history</h3><p class="history-intro">Decisions stay private to this review unless a demonstration publisher explicitly shares one for reuse. This local demo has no identity verification.</p><p class="quiet-note">Looking for recurring patterns? <a href="/decision-log.html?review=${encodeURIComponent(d.id)}">Explore fictional earlier decisions related to this review →</a>. These are illustrative scenarios, not recorded decisions on this document.</p>${d.history.length?d.history.map(e=>{const publications=d.publications.filter(p=>p.decision_id===e.id);const active=publications.some(p=>p.status==='active');const sources=e.considered_sources||[];const unique=[...new Map(sources.map(u=>[u.anchor,u])).values()];return `<article class="history-event"><strong>${esc(decisionLabel[e.decision])}</strong><small>${esc(e.reviewer)} · ${esc(e.timestamp)} · ${esc(e.sha256.slice(0,12))}…</small><p>${esc(e.rationale)}</p>${e.conditions?`<p><strong>Decision conditions:</strong> ${esc(e.conditions)}</p>`:''}<small>Considered: ${e.finding_ids.length?esc(e.finding_ids.map(id=>titles.get(id)||id).join('; ')):'none marked'} · Event ${esc(e.id)}</small>${publications.map(p=>`<div class="publication-status"><strong>${p.status==='active'?'Shared for reuse in this demo':'Withdrawn from active reuse'}</strong><p>Context: ${esc(p.context)}</p><p>Limits: ${esc(p.reuse_limits)}</p><small>Publisher ${esc(p.authoriser)} · ${esc(p.timestamp)} · Publication ${esc(p.id)}</small>${p.withdrawal?`<p>Withdrawn by ${esc(p.withdrawal.actor)}: ${esc(p.withdrawal.reason)}</p>`:`<details><summary>Withdraw this precedent</summary><form class="withdraw-form" data-publication="${esc(p.id)}"><label class="field">Your name<input name="actor" required maxlength="100"></label><label class="field">Reason for withdrawal<textarea name="reason" required maxlength="1000"></textarea></label><label class="acknowledge"><input type="checkbox" name="acknowledged" required> I am acting as the named demonstration publisher. This identity is not verified.</label><button class="secondary" type="submit">Withdraw from search</button></form></details>`}</div>`).join('')}${!active&&d.analysis.route!=='blocked_extraction'&&unique.length?`<details class="publish-details"><summary>Share this decision as a precedent</summary><p>Choose the exact wording considered. Sharing adds context for later reviewers; it never approves another contract or changes its route.</p><form class="publish-form" data-decision="${esc(e.id)}"><label class="field">Source passage<select name="source_anchor" required>${unique.map(u=>`<option value="${esc(u.anchor)}">${esc(u.text.slice(0,110))}${u.text.length>110?'…':''}</option>`).join('')}</select></label><label class="field">Demonstration publisher<input name="authoriser" required maxlength="100" placeholder="Name shown with this publication"></label><label class="field">Commercial context<textarea name="context" required maxlength="1000" placeholder="What situation made this decision applicable?"></textarea></label><label class="field">Limits on reuse<textarea name="reuse_limits" required maxlength="1000" placeholder="What must a later reviewer check before relying on this case?"></textarea></label><label class="acknowledge"><input type="checkbox" name="acknowledged" required> I am acting as a demonstration legal reviewer and have checked the source, decision and conditions. Identity is self-attested in this local prototype.</label><button class="primary" type="submit">Publish for demo reuse</button></form></details>`:!publications.length?`<p class="uncertainty">To share this decision, record a new decision with a source-linked finding marked as considered and complete extraction.</p>`:''}</article>`}).join(''):'<div class="empty">No human decision recorded for this exact document yet.</div>'}`}
function correctionHistoryView(d){return `<section class="correction-history"><h3 class="section-title">Comparison corrections</h3><p class="history-intro">These notes concern Chug's comparison, separately from legal decisions. An unshared note remains private to this review.</p>${d.corrections.length?d.corrections.map(c=>{const active=c.publications.some(p=>p.status==='active');return `<article class="history-event"><strong>${esc(c.relationship.replaceAll('_',' '))}</strong><small>${esc(c.reviewer)} · ${esc(c.timestamp)} · source ${esc(c.document_sha256.slice(0,12))}… · reference ${esc(c.reference_sha256.slice(0,12))}…</small><p>${esc(c.explanation)}</p><blockquote>${esc(c.source_text||'No incoming passage')}</blockquote><p>Reference: ${esc(c.reference_text||'No reference passage')}</p><small>Original Chug finding: ${esc(c.proposed_category)} · Event ${esc(c.id)}</small>${c.publications.map(p=>`<div class="publication-status"><strong>${p.status==='active'?'Shared as a comparison lesson':'Withdrawn from active reuse'}</strong><p>Context: ${esc(p.context)}</p><p>Limits: ${esc(p.reuse_limits)}</p><small>Publisher ${esc(p.publisher)} · ${esc(p.timestamp)}</small>${p.status==='active'?`<details><summary>Withdraw lesson</summary><form class="correction-withdraw-form" data-publication="${esc(p.id)}"><label class="field">Your name<input name="actor" required maxlength="100"></label><label class="field">Reason<textarea name="reason" required maxlength="1000"></textarea></label><label class="acknowledge"><input type="checkbox" name="acknowledged" required> I am acting as a demonstration legal reviewer; identity is self-attested.</label><button class="secondary" type="submit">Withdraw from search</button></form></details>`:''}</div>`).join('')}${!active&&d.analysis.route!=='blocked_extraction'?`<details class="publish-details"><summary>Share this correction for later reviews</summary><p>Only its evidence and your explanation are reused. Later applicability remains unverified.</p><form class="correction-publish-form" data-correction="${esc(c.id)}"><label class="field">Demonstration publisher<input name="publisher" required maxlength="100"></label><label class="field">Commercial context<textarea name="context" required maxlength="1000"></textarea></label><label class="field">Limits on reuse<textarea name="reuse_limits" required maxlength="1000"></textarea></label><label class="acknowledge"><input type="checkbox" name="acknowledged" required> I checked this correction and am acting as a demonstration legal reviewer. Identity is self-attested.</label><button class="primary" type="submit">Share comparison lesson</button></form></details>`:''}</article>`}).join(''):'<p class="empty">No comparison corrections recorded for this document.</p>'}</section>`}
function homeView(){
  const counts=Object.fromEntries(['escalate','review_required','routine_candidate','blocked_extraction'].map(key=>[key,queueItems(key).length]));
  const pending=state.queue.filter(item=>!item.latest_decision);
  const referenceKind=!state.reference?.current?'loading reference':state.reference.current.kind==='bundled'?'bundled mutual NDA sample':'selected synthetic mutual NDA reference';
  return `<section class="home"><h1>Review what needs attention</h1><p>Chug compares your reference documents, brings differences and relevant past decisions together, and leaves the decision with you.</p><div class="home-actions"><button class="primary" type="button" data-start>${pending.length?'Start reviewing':'Open review queue'}</button></div><section class="home-work" aria-labelledby="home-work-title"><h2 id="home-work-title">Work awaiting a decision</h2><div class="home-counts"><button type="button" class="summary-route" data-filter="escalate"><strong>${counts.escalate}</strong><span>Needs closer review</span><span aria-hidden="true">→</span></button><button type="button" class="summary-route" data-filter="review_required"><strong>${counts.review_required}</strong><span>Needs judgement</span><span aria-hidden="true">→</span></button><button type="button" class="summary-route" data-filter="routine_candidate"><strong>${counts.routine_candidate}</strong><span>Looks routine</span><span aria-hidden="true">→</span></button>${counts.blocked_extraction?`<button type="button" class="summary-route" data-filter="blocked_extraction"><strong>${counts.blocked_extraction}</strong><span>Analysis blocked</span><span aria-hidden="true">→</span></button>`:''}</div></section><div class="home-bottom"><p>Synthetic mutual NDA demonstration · Every route needs a human decision.</p><p>Reference for new uploads: <button class="text-action" type="button" data-page="reference">${referenceKind}</button>. Each existing review keeps the reference selected when it entered the queue.</p></div></section>`
}
function exploreView(){return `<section class="explore-page" aria-labelledby="explore-title"><button class="text-action explore-back" type="button" data-page="home">← Back to contract review</button><div class="explore-intro"><span class="eyebrow">Explore Chug</span><h1 id="explore-title">One working legal journey. A wider idea to test.</h1><p>Chug currently helps a fictional Legal team compare mutual NDAs, inspect evidence and past decisions, and record its own judgement. Other workspaces below are product concepts, not working features.</p></div><section class="core-summary" aria-labelledby="core-title"><div><span class="eyebrow">Working foundation</span><h2 id="core-title">Evidence first, judgement with people</h2></div><p>The legal demo preserves the source, checks it against a chosen reference, shows differences and relevant history, then records a human decision. Reuse of a decision requires a separate explicit publication step.</p></section><div class="workspace-heading"><div><span class="eyebrow">Available now</span><h2>Legal review</h2></div><p>Open the real, synthetic mutual NDA review journey.</p></div><article class="workspace-card workspace-card-active"><div><span class="workspace-status">Working demo</span><h3>Legal · mutual NDAs</h3><p>Review an exception, inspect its source and a past decision, then record your decision.</p></div><button class="primary" type="button" data-page="queue">Open legal review queue →</button></article><section class="future-workspaces" aria-labelledby="future-title"><div class="workspace-heading"><div><span class="eyebrow">Possible later work</span><h2 id="future-title">Other team workspaces</h2></div><p>Concepts only. Each would need its own reference material, specialist checks and review authority.</p></div><div class="workspace-grid"><article class="workspace-card workspace-card-concept" aria-label="People and Culture: concept, not included in this demo"><h3>People &amp; Culture</h3><p>Compare policy updates with approved guidance and route exceptions to the right people.</p></article><article class="workspace-card workspace-card-concept" aria-label="Finance: concept, not included in this demo"><h3>Finance</h3><p>Review changes to recurring commercial terms against a controlled baseline.</p></article><article class="workspace-card workspace-card-concept" aria-label="Product and Engineering: concept, not included in this demo"><h3>Product &amp; Engineering</h3><p>Trace proposed changes to a technical standard and its earlier decisions.</p></article><article class="workspace-card workspace-card-concept" aria-label="Customer Support: concept, not included in this demo"><h3>Customer Support</h3><p>Bring a proposed response, relevant policy and prior resolutions together for human review.</p></article></div><p class="quiet-note">No other department's data, rules or permissions are part of this demo. A Legal precedent would never become guidance for another team by default.</p></section></section>`}
function queueView(){const shown=queueItems();return `<section class="queue-intro"><h1>${filterLabel[state.filter]}</h1><p>${state.filter==='all'?'Choose a contract in priority order. Recorded decisions remain available here.':`${shown.length} ${shown.length===1?'contract':'contracts'} awaiting a human decision in this category.`} Routes organise attention; they are not legal outcomes.</p>${shown.length?'<button class="primary" type="button" data-start>Open next contract</button>':''}</section>`}
function referenceView(){const current=state.reference?.current;const available=state.reference?.available||[];return `<section class="reference-page"><h1>Reference standards</h1><p>Chug keeps a family-aware library of fictional contract standards with their source, applicability, version and lifecycle status. In the local prototype, fictional Legal uploads are registered Active and may be proposed for human confirmation. A proposal does not compare documents or decide a contract. The bundled NDA remains the legacy baseline for existing NDA reviews.</p>${state.staticDemo?'<p class="quiet-note">The public demo is a static, read-only snapshot of fictional examples. It has no public uploads, decisions, AI requests or live multi-family comparison.</p>':''}${referenceLibraryView()}${!state.staticDemo?`${current?`<section class="reference-library"><h2>Legacy NDA review binding</h2><p>Existing NDA reviews retain the exact reference they were created with.</p><div class="reference-card"><strong>${esc(current.filename)}</strong><span>${current.kind==='bundled'?'Legacy NDA comparison baseline':'Selected NDA reference'} · SHA-256 ${esc(current.sha256)}</span><span>Extraction ${esc(current.coverage.status)} · source ${esc(current.source_integrity)} · ${current.units.length} anchored passages</span><a href="/api/references/${esc(current.sha256)}/original">Download exact reference DOCX ↗</a></div></section>`:'<p class="loading">Loading current NDA reference…</p>'}<div class="home-actions"><label class="secondary upload-button">Add fictional Legal reference DOCX<input id="reference-upload" type="file" accept=".docx" hidden></label></div>${referenceCandidateView()}${available.length>1?`<div class="reference-options"><h2>Saved NDA references</h2>${available.filter(item=>item.sha256!==current?.sha256).map(item=>`<button class="secondary" type="button" data-select-reference="${esc(item.sha256)}">Use ${esc(item.filename)} (${item.kind==='bundled'?'legacy baseline':'uploaded synthetic'})</button>`).join('')}</div>`:''}${matchIntakeView()}<p class="quiet-note">Superseded and Withdrawn standards remain visible for provenance and cannot be proposed for a new match. Research candidates are not Active standards.</p>${current?`<details class="reference-full"><summary>Inspect current NDA wording</summary>${fullText({document:current})}</details>`:''}`:''}${state.staticDemo?researchView():''}</section>`}
function referenceCandidateView(){const file=state.referenceCandidate;return file?`<div class="reference-candidate"><strong>Selected: ${esc(file.name)}</strong><span>${(file.size/1024).toFixed(0)} KB · supported fictional standards enter the local library as Active for applicability proposals; upload does not compare or review the incoming contract</span><button class="primary" type="button" data-use-reference>Register standard</button><button class="text-action" type="button" data-cancel-reference>Cancel</button></div>`:''}
function matchIntakeView(){return `<section class="reference-library match-intake"><h2>Check reference applicability</h2><p>Upload a synthetic incoming DOCX to inspect its family and source evidence and receive a candidate proposal. This does not compare documents or enter the NDA review queue.</p><label class="secondary upload-button">Choose incoming DOCX<input id="match-upload" type="file" accept=".docx" hidden></label>${state.matchResult?matchResultView(state.matchResult):''}</section>`}
function matchResultView(result){const proposal=result.proposal||{};const candidate=proposal.proposal;const source=proposal.context?.dimensions||{};return `<article class="reference-detail match-result"><h3>Applicability proposal · ${esc(proposal.status||'unknown')}</h3><p>Incoming: ${esc(result.incoming?.filename)} · SHA-256 <code>${esc(result.incoming?.sha256)}</code> · assessed ${esc(result.assessed_at)}</p><p>${esc(proposal.reason||'No proposal reason recorded.')}</p>${candidate?`<p><strong>Suggested standard:</strong> ${esc(candidate.display_name)} · ${esc(candidate.status?.replaceAll('_',' ')||'status unavailable')} · version ${esc(candidate.version)} · ${esc(candidate.reference_id)} · SHA-256 <code>${esc(candidate.sha256)}</code></p><ul>${(candidate.reasons||[]).map(item=>`<li>${esc(item.dimension.replaceAll('_',' '))}: ${esc(item.value)}${(item.evidence||[]).map(e=>`<blockquote>${esc(e.text)} <small>${esc(e.anchor)}</small></blockquote>`).join('')}</li>`).join('')}</ul>`:''}${proposal.questions?.length?`<p><strong>Need to establish:</strong> ${esc(proposal.questions.join(' '))}</p>`:''}<details><summary>Context, alternatives and exclusions</summary><ul>${Object.entries(source).map(([name,item])=>`<li><strong>${esc(name.replaceAll('_',' '))}:</strong> ${esc(item.state)}${item.value?` · ${esc(item.value)}`:''}${(item.evidence||[]).map(e=>`<blockquote>${esc(e.text)} <small>${esc(e.anchor)}</small></blockquote>`).join('')}</li>`).join('')}</ul><h4>Alternatives</h4><ul>${(proposal.alternatives||proposal.eligible||[]).map(item=>`<li>${esc(item.display_name)} · ${esc(item.status||'')} · ${esc(item.version)} · ${esc(item.sha256)}</li>`).join('')||'<li>None</li>'}</ul><h4>Excluded</h4><ul>${(proposal.excluded||[]).map(item=>`<li>${esc(item.display_name)} · ${esc(item.status||'')} · ${esc((item.reasons||[]).join('; '))}</li>`).join('')||'<li>None</li>'}</ul></details><p>Human decision required. Confirmation and comparison have not occurred.</p><a href="${esc(result.original_url||('/api/reference-matches/'+result.incoming.sha256+'/original'))}">Download incoming original ↗</a></article>`}
function referenceLibraryView(){const localRows=state.referenceLibrary?.references||[];const publicRows=state.research?.references||[];const rows=localRows.length?localRows:publicRows.map(item=>({reference_id:item.id,display_name:item.name,family:item.family,status:'research_candidate',version:item.version,provenance:'synthetic_research_catalogue',source_integrity:'static_demo_source',sha256:item.sha256,download:item.download}));if(!rows.length)return `<section class="reference-library"><h2>Available reference library</h2><p>The public snapshot does not include reference-standard records.</p></section>`;const detail=state.referenceDetail;const applicability=detail?.applicability||{};const label=value=>({bundled_demo_baseline:'Bundled demo baseline',verified_research_catalogue:'Synthetic research catalogue',synthetic_research_catalogue:'Synthetic research catalogue',locally_uploaded_synthetic_reference:'Fictional Legal upload'}[value]||value||'Source not recorded');const showRow=item=>`<li><div><strong>${esc(item.display_name)}</strong><span>${esc(item.family.replaceAll('_',' '))} · ${esc((item.status||'unknown').replaceAll('_',' '))} · version ${esc(item.version||'unknown')}</span><small>Provenance: ${esc(label(item.provenance))} · ${esc(item.source_integrity||'source integrity unavailable')} · SHA-256 ${esc(item.sha256)}</small></div>${item.download?`<a href="${esc(item.download)}" download>Original DOCX ↗</a>`:!state.staticDemo?`<button type="button" class="text-action" data-reference-detail="${esc(item.reference_id)}">View details</button>`:''}</li>`;const baselines=rows.filter(item=>item.status==='legacy_nda_baseline');const candidates=rows.filter(item=>item.status==='research_candidate');const standards=rows.filter(item=>!['legacy_nda_baseline','research_candidate'].includes(item.status));return `<section class="reference-library"><h2>Available reference library</h2><p>Standards and source materials are grouped by provenance. Family, version and lifecycle status stay visible.</p>${standards.length?`<h3>Fictional Legal standards</h3><ul>${standards.map(showRow).join('')}</ul>`:''}${baselines.length?`<h3>Legacy NDA comparison baseline</h3><p>Retained for existing NDA reviews. It is excluded from new applicability matching until its direction and purpose are confirmed.</p><ul>${baselines.map(showRow).join('')}</ul>`:''}${candidates.length?`<h3>Synthetic research catalogue · research candidates</h3><p>${candidates.length} fictional source specimens; not Active standards and excluded from new matches.</p><ul>${candidates.map(showRow).join('')}</ul>`:''}${detail?`<details class="reference-detail" open><summary>${esc(detail.display_name)} · ${esc(detail.status.replaceAll('_',' '))}</summary><p>Family: ${esc(detail.family)} · Status: ${esc(detail.status)} · Version: ${esc(detail.version)} · Provenance: ${esc(label(detail.provenance))}</p><p>Original: ${esc(detail.original_filename)} · SHA-256 <code>${esc(detail.sha256)}</code> · source ${esc(detail.source_integrity)}</p>${detail.scope?`<p>Scope: ${esc(detail.scope)}${detail.scope_anchor?` · source ${esc(detail.scope_anchor)}`:''}</p>`:''}<details><summary>Applicability and source evidence</summary><ul>${Object.entries(applicability).map(([name,item])=>`<li><strong>${esc(name.replaceAll('_',' '))}:</strong> ${esc(item.state)}${item.value?` · ${esc(item.value)}`:''}${(item.evidence||[]).map(evidence=>`<blockquote>${esc(evidence.text)} <small>${esc(evidence.anchor)}</small></blockquote>`).join('')}</li>`).join('')}</ul></details><p>Extraction: ${esc(detail.extraction.status)} · ${detail.extraction.passage_count} passages · ${detail.extraction.limitations.length?`Limitations: ${esc(detail.extraction.limitations.join('; '))}`:'No extraction limitations recorded.'}</p><a href="${esc(detail.original_url)}">Download exact original DOCX ↗</a>${detail.kind==='uploaded_synthetic'&&detail.status==='active'?`<form class="reference-status-form" data-reference-status="superseded"><label class="field">Reason to supersede<input name="reason" required maxlength="1000"></label><button class="secondary" type="submit">Mark Superseded</button></form><form class="reference-status-form" data-reference-status="withdrawn"><label class="field">Reason to withdraw<input name="reason" required maxlength="1000"></label><button class="secondary" type="submit">Mark Withdrawn</button></form>`:''}${detail.status_history?.length?`<details><summary>Status history</summary><ul>${detail.status_history.map(event=>`<li>${esc(event.from)} → ${esc(event.to)} · ${esc(event.timestamp)} · ${esc(event.reason)}</li>`).join('')}</ul></details>`:''}</details>`:''}</section>`}
function researchView(){
  const r=state.research;
  if(!r)return '';
  const entries=(rows)=>rows.map(item=>'<li><strong>'+esc(item.name)+'</strong> <span class="research-meta">'+esc(item.family||item.status||'Unassessed')+'</span> <a href="'+esc(item.download)+'" download>Original DOCX</a></li>').join('');
  return '<section class="research-library"><h2>Incoming example documents · not standards</h2>'+
    '<p>These fictional examples are separate from the reference library and have not been assessed or compared.</p>'+
    '<details open><summary>'+r.routine_clients.length+' routine-looking client examples (not evaluated)</summary><ul>'+entries(r.routine_clients)+'</ul></details>'+
    '<details><summary>'+r.challenge_cases.length+' incoming challenge examples (not evaluated)</summary><ul>'+entries(r.challenge_cases)+'</ul></details>'+
    '<p class="quiet-note">Downloading an example does not mean Chug has assessed it. The public snapshot provides no upload, decision or live comparison controls.</p></section>';
}
function helpView(){return `<section class="help-page"><h1>How Chug works</h1><ol><li>Use a fictional standard from the family-aware reference library, or upload one in the local prototype. Local fictional Legal uploads enter the library as Active; applicability still needs human confirmation.</li><li>Chug accounts for supported source content, compares wording and checks for selected whole-document exceptions.</li><li>Review the exact incoming and reference wording, alongside relevant past decisions.</li><li>A person records the legal decision. Sharing a past decision for later search is a separate action.</li></ol><p>The public demo is a static, read-only snapshot. It does not accept public uploads, record decisions, make AI requests or run live multi-family comparisons.</p><h2>What the labels mean</h2><dl><dt>Needs closer review</dt><dd>A potentially consequential provision or missing protection needs closer review.</dd><dt>Needs judgement</dt><dd>A change or uncertainty needs interpretation.</dd><dt>Looks routine</dt><dd>Required checks completed within their stated scope; a person still confirms the parties, purpose and decision.</dd><dt>Analysis blocked</dt><dd>Chug could not account for all content, so comparison must not be treated as complete.</dd></dl><h2>What Chug cannot decide</h2><p>These checks are limited to supported synthetic mutual NDAs. They may miss unfamiliar legal effects. Similar historical wording is context, not permission to approve. AI is optional, off by default and cannot change review routes.</p><p><button class="text-action" type="button" data-page="explore">Explore the wider product concept</button></p></section>`}
function historyDrawer(d){const scope=d.analysis.history_scope||{historical_records:0,active_published_records:0};const choices=[...new Set(d.analysis.precedents.map(row=>row.decision))];const shown=state.historyFilter==='all'?d.analysis.precedents:d.analysis.precedents.filter(row=>row.decision===state.historyFilter);return `<aside class="history-drawer" role="complementary" aria-label="Similar past decisions"><div class="drawer-head"><div><h3>Similar past decisions</h3><p>${d.analysis.precedents.length} related shown · ${scope.historical_records} historical + ${scope.active_published_records} published records searched</p></div><button type="button" class="secondary" data-history-close>Close</button></div><p class="quiet-note">Wording and topic are matched lexically. A past decision does not approve this contract.</p><label class="history-filter">Show <select id="history-filter"><option value="all">All related decisions</option>${choices.map(value=>`<option value="${esc(value)}" ${state.historyFilter===value?'selected':''}>${esc(value.replaceAll('_',' '))}</option>`).join('')}</select></label>${shown.map(precedentView).join('')||'<p class="empty">No related case with that decision.</p>'}${state.historySource?`<section class="history-source"><h4>Original reviewed contract · ${esc(state.historySource.document.filename)}</h4><a href="/api/history/${esc(state.historySourceId)}/original">Download exact historical DOCX ↗</a>${fullText(state.historySource)}<button class="text-action" type="button" data-source-close>Close original</button></section>`:''}</aside>`}
function startReviewing(){const next=state.page==='queue'?queueItems()[0]:state.queue.find(item=>!item.latest_decision);if(!next)return navigate('queue');if(state.page==='home'){state.filter=next.route;sessionStorage.setItem('chug.queueFilter',next.route)}return select(next.id)}
function renderPage(anchor){el('shell').className='shell page-'+state.page;document.title=state.page==='explore'?'Explore Chug · Potential workspaces':'Chug · Contract review';document.querySelectorAll('.main-nav [data-page]').forEach(button=>button.setAttribute('aria-current',button.dataset.page===state.page||(state.page==='review'&&button.dataset.page==='queue')?'page':'false'));if(state.page==='home')el('workspace').innerHTML=homeView();else if(state.page==='queue')el('workspace').innerHTML=queueView();else if(state.page==='reference')el('workspace').innerHTML=referenceView();else if(state.page==='help')el('workspace').innerHTML=helpView();else if(state.page==='explore')el('workspace').innerHTML=exploreView();else render();document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>navigate('queue',button.dataset.filter));document.querySelectorAll('[data-start]').forEach(button=>button.onclick=startReviewing);document.querySelectorAll('[data-add-upload]').forEach(button=>button.onclick=()=>el('upload').click());const referenceUpload=el('reference-upload');if(referenceUpload)referenceUpload.onchange=uploadReference;const matchUpload=el('match-upload');if(matchUpload)matchUpload.onchange=uploadForMatch;const useReference=el('workspace').querySelector('[data-use-reference]');if(useReference)useReference.onclick=commitReference;const cancelReference=el('workspace').querySelector('[data-cancel-reference]');if(cancelReference)cancelReference.onclick=()=>{state.referenceCandidate=null;renderPage()};document.querySelectorAll('[data-select-reference]').forEach(button=>button.onclick=()=>chooseReference(button.dataset.selectReference));document.querySelectorAll('[data-reference-detail]').forEach(button=>button.onclick=async()=>{try{state.referenceDetail=await api('/api/reference-library/'+encodeURIComponent(button.dataset.referenceDetail));renderPage()}catch(err){toast(err.message)}});el('workspace').querySelectorAll('.reference-status-form').forEach(form=>form.onsubmit=updateReferenceStatus);applyStaticDemo();if(anchor)requestAnimationFrame(()=>{const target=document.getElementById(anchor);target?.classList.add('evidence-focus');target?.scrollIntoView({behavior:'smooth',block:'center'})})}
function reviewNav(d){return `<nav class="tabs" aria-label="Review evidence and tools"><button class="tab ${state.tab==='overview'?'active':''}" data-tab="overview" ${state.tab==='overview'?'aria-current="page"':''}>Review</button><button class="tab ${state.tab==='document'?'active':''}" data-tab="document" ${state.tab==='document'?'aria-current="page"':''}>Full document</button><button class="tab ${state.tab==='reference'?'active':''}" data-tab="reference" ${state.tab==='reference'?'aria-current="page"':''}>Reference</button><button class="tab ${state.tab==='assurance'?'active':''}" data-tab="assurance" ${state.tab==='assurance'?'aria-current="page"':''}>Check coverage</button><button class="tab ${state.tab==='history'?'active':''}" data-tab="history" ${state.tab==='history'?'aria-current="page"':''}>Review history${d.history.length||d.corrections.length?` (${d.history.length+d.corrections.length})`:''}</button></nav>`}
function render(){
  const d=state.detail;if(!d)return;
  const content=state.tab==='overview'?overview(d):state.tab==='assurance'?assuranceView(d):state.tab==='document'?fullText(d):state.tab==='reference'?fullText({document:d.reference}):historyView(d)+correctionHistoryView(d);
  el('workspace').innerHTML=`<div class="doc-head"><div><button class="text-action" type="button" data-return-queue>← Back to ${state.filter==='all'?'review queue':filterLabel[state.filter].toLowerCase()}</button><h2>${esc(d.display_name)}</h2><p class="doc-context">Compared with the reference selected for this review · A person decides what happens next.</p></div></div><details class="document-details"><summary>Document details and original files</summary><p>Incoming: ${esc(d.id)} · ${esc(d.document.filename)} · SHA-256 <code>${esc(d.document.sha256)}</code></p><p>Applicable reference: ${esc(d.reference.filename)} · SHA-256 <code>${esc(d.reference.sha256)}</code>. Existing reviews retain their selected reference.</p><a href="/api/contracts/${encodeURIComponent(d.id)}/original">Download original DOCX ↗</a></details>${state.tab==='overview'?content:reviewNav(d)+content}${state.historyOpen?historyDrawer(d):''}`;
  el('workspace').querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>setTab(button.dataset.tab));
  el('workspace').querySelectorAll('[data-return-queue]').forEach(button=>button.onclick=()=>navigate('queue',state.filter));
  el('workspace').querySelectorAll('[data-anchor]').forEach(link=>link.onclick=event=>{event.preventDefault();state.findingOpen=link.closest('.finding')?.id||state.findingOpen;setTab(link.dataset.kind==='reference'?'reference':'document',link.dataset.anchor)});
  el('workspace').querySelectorAll('[data-precedent-source]').forEach(button=>button.onclick=async()=>{try{const id=button.dataset.precedentSource;if(id.startsWith('H')){state.historySource=await api(`/api/history/${encodeURIComponent(id)}`);state.historySourceId=id;render();const target=document.getElementById(button.dataset.anchor);target?.classList.add('evidence-focus');target?.scrollIntoView({behavior:'smooth',block:'center'})}else{await select(id);setTab('document',button.dataset.anchor)}}catch(err){toast(err.message)}});
  el('workspace').querySelectorAll('[data-source-close]').forEach(button=>button.onclick=()=>{state.historySource=null;state.historySourceId=null;render()});
  el('workspace').querySelectorAll('[data-open-finding]').forEach(button=>button.onclick=()=>{const target=el('finding-'+button.dataset.openFinding);target.open=true;target.scrollIntoView({behavior:'smooth',block:'center'})});
  el('workspace').querySelectorAll('[data-open-decision]').forEach(button=>button.onclick=()=>{el('decision-section').open=true;el('decision-section').scrollIntoView({behavior:'smooth',block:'start'});el('decision-section').querySelector('summary')?.focus({preventScroll:true})});
  el('workspace').querySelectorAll('[data-history-open]').forEach(button=>button.onclick=()=>{state.historyOpen=true;render();el('workspace').querySelector('[data-history-close]')?.focus()});
  el('workspace').querySelectorAll('[data-history-close]').forEach(button=>button.onclick=()=>{state.historyOpen=false;render();el('workspace').querySelector('[data-history-open]')?.focus()});
  const historyFilter=el('history-filter');if(historyFilter)historyFilter.onchange=event=>{state.historyFilter=event.target.value;state.historySource=null;state.historySourceId=null;render()};
  el('workspace').querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));
  const form=el('decision-form');if(form)form.onsubmit=submitDecision;
  el('workspace').querySelectorAll('.publish-form').forEach(form=>form.onsubmit=submitPublication);
  el('workspace').querySelectorAll('.withdraw-form').forEach(form=>form.onsubmit=submitWithdrawal);
  el('workspace').querySelectorAll('.correction-form').forEach(form=>form.onsubmit=submitCorrection);
  el('workspace').querySelectorAll('.correction-publish-form').forEach(form=>form.onsubmit=submitCorrectionPublication);
  el('workspace').querySelectorAll('.correction-withdraw-form').forEach(form=>form.onsubmit=submitCorrectionWithdrawal);
  const ai=el('ai-run');if(ai)ai.onclick=()=>runAI(ai.dataset.finding)
  if(state.findingOpen&&state.tab==='overview'){const open=el(state.findingOpen);if(open)open.open=true}
  applyStaticDemo();
}
async function submitDecision(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/decisions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:state.id,reviewer:data.get('reviewer'),decision:data.get('decision'),rationale:data.get('rationale'),conditions:data.get('conditions'),finding_ids:data.getAll('finding')})});toast('Human decision recorded with this document hash.');state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);await loadQueue();setTab('history')}catch(err){toast(err.message)}}
async function submitPublication(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/precedents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:state.id,decision_id:form.dataset.decision,source_anchor:data.get('source_anchor'),authoriser:data.get('authoriser'),context:data.get('context'),reuse_limits:data.get('reuse_limits'),role:'demo_legal_reviewer',acknowledged:data.get('acknowledged')==='on'})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);setTab('history');toast('Shared as a demonstration precedent. Later reviews still need a human decision.')}catch(err){toast(err.message)}}
async function submitWithdrawal(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api(`/api/precedents/${encodeURIComponent(form.dataset.publication)}/withdraw`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:data.get('actor'),reason:data.get('reason'),role:'demo_legal_reviewer',acknowledged:data.get('acknowledged')==='on'})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);setTab('history');toast('Precedent withdrawn from active search; history retained.')}catch(err){toast(err.message)}}
async function submitCorrection(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/corrections',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:state.id,finding_id:form.dataset.finding,source_anchor:data.get('source_anchor'),reference_anchor:data.get('reference_anchor'),relationship:data.get('relationship'),explanation:data.get('explanation'),reviewer:data.get('reviewer')})});await loadQueue();await setTab('history');toast('Comparison correction saved. It is not a legal decision or reusable lesson.')}catch(err){toast(err.message)}}
async function submitCorrectionPublication(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/correction-lessons',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({correction_id:form.dataset.correction,publisher:data.get('publisher'),context:data.get('context'),reuse_limits:data.get('reuse_limits'),role:'demo_legal_reviewer',acknowledged:data.get('acknowledged')==='on'})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);setTab('history');toast('Comparison lesson shared for later reviews. It cannot change routing or approve a contract.')}catch(err){toast(err.message)}}
async function submitCorrectionWithdrawal(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api(`/api/correction-lessons/${encodeURIComponent(form.dataset.publication)}/withdraw`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:data.get('actor'),reason:data.get('reason'),role:'demo_legal_reviewer',acknowledged:data.get('acknowledged')==='on'})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);setTab('history');toast('Comparison lesson withdrawn from active search; its history remains.')}catch(err){toast(err.message)}}
async function runAI(findingId){if(!confirm('Send the selected synthetic source and reference passages to OpenAI for an optional language comparison? This may incur API charges within configured caps.'))return;try{await api('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:state.id,finding_id:findingId})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);render();toast('Live AI interpretation received.')}catch(err){toast(err.message)}}
async function chooseReference(sha256){const selected=state.reference?.available.find(item=>item.sha256===sha256);if(!selected)return;try{state.reference=await api('/api/reference/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sha256})});renderPage();toast('Reference selected for new incoming uploads. Existing reviews keep their original reference.')}catch(err){toast(err.message)}}
function uploadReference(event){const file=event.target.files[0];event.target.value='';if(!file)return;if(!file.name.toLowerCase().endsWith('.docx')){toast('Choose a synthetic DOCX reference.');return}state.referenceCandidate=file;renderPage()}
async function commitReference(){const file=state.referenceCandidate;if(!file)return;const form=new FormData();form.append('file',file);try{const result=await api('/api/reference/upload',{method:'POST',body:form});state.reference=result;if(!state.staticDemo)state.referenceLibrary=await api('/api/reference-library');state.referenceDetail=result.library_item?await api('/api/reference-library/'+encodeURIComponent(result.library_item.reference_id)):null;state.referenceCandidate=null;renderPage();const selected=result.library_item?.sha256===result.current?.sha256;toast(result.library_item?.family==='customer_order'?'Customer-order standard registered Active; NDA baseline unchanged.':selected?'NDA standard registered Active and selected for new NDA uploads.':'Existing reference identity retained; selected baseline unchanged.')}catch(err){toast(err.message)}}
async function uploadForMatch(event){const file=event.target.files[0];event.target.value='';if(!file)return;if(!file.name.toLowerCase().endsWith('.docx')){toast('Choose a synthetic DOCX contract.');return}const form=new FormData();form.append('file',file);try{const result=await api('/api/reference-matches',{method:'POST',body:form});state.matchResult=await api('/api/reference-matches/'+encodeURIComponent(result.incoming.sha256));renderPage();toast('Applicability proposal saved. No comparison or contract decision was made.')}catch(err){toast(err.message)}}
async function updateReferenceStatus(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/reference-library/'+encodeURIComponent(state.referenceDetail.reference_id)+'/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:form.dataset.referenceStatus,reason:data.get('reason')})});state.referenceLibrary=await api('/api/reference-library');state.referenceDetail=await api('/api/reference-library/'+encodeURIComponent(state.referenceDetail.reference_id));renderPage();toast('Reference status saved; its original and prior matches remain traceable.')}catch(err){toast(err.message)}}
el('filter').onchange=event=>navigate('queue',event.target.value);el('upload-trigger').onclick=()=>el('upload').click();el('upload').onchange=async event=>{const file=event.target.files[0];if(!file)return;const form=new FormData();form.append('file',file);try{const data=await api('/api/upload',{method:'POST',body:form});await loadQueue();await select(data.id);toast('DOCX added to the local synthetic workspace.')}catch(err){toast(err.message)}event.target.value=''};
window.addEventListener('popstate',()=>{const next=route();navigate(next.page,next.id,next.tab,next.anchor,true)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.historyOpen){state.historyOpen=false;render();el('workspace').querySelector('[data-history-open]')?.focus()}});
loadQueue().then(async()=>{state.reference=await api('/api/reference');if(state.staticDemo){try{state.research=await api('/demo-data/research.json')}catch(error){console.warn('Research fixtures are not exported:',error.message)}}else{try{state.referenceLibrary=await api('/api/reference-library')}catch(error){console.warn('Reference library could not be loaded:',error.message)}}const next=route();await navigate(next.page,next.id,next.tab,next.anchor,true)}).catch(err=>el('workspace').innerHTML=`<p class="empty">Could not load the local workspace: ${esc(err.message)}</p>`);
